1	import React from 'react';
2	import {FONT, widthOf} from '../../../lib/type';
3	import {useUid} from '../../../lib/uid';
4	
5	/**
6	 * FloodStationHero, the fresh authored hero group for the 2026-10-15 edition.
7	 *
8	 * ONE solar flood station carries the film, drawn as the design UT San Antonio describes and never
9	 * as an installed unit. A weathered galvanized pipe post stands in a small concrete footing at a
10	 * San Antonio curb. Low on its front a slotted strut rail holds FOUR optical water-level pods at
11	 * four different heights, each a small housing with a round lens and a ring lamp that lights as the
12	 * water reaches it. A grey flexible conduit runs up the right side of the post, sags once, and
13	 * enters the instrument housing near the top. The housing is a fibreglass enclosure, hung a few
14	 * degrees off level, with a dented overhanging cap, hinges on the left, a latch on the right, a
15	 * battery bar window, a row of four small weather lamps (rain, temperature, humidity, light) and one
16	 * hooded amber risk lamp. On top sit a rain funnel and a light dome; a louvred shield for the
17	 * temperature and humidity sensor hangs from an arm on the right. A small dark blue solar panel with
18	 * a worn corner tilts toward the low sun from a bracket at the post top, and a short black whip
19	 * antenna leans off the cap.
20	 *
21	 * The same group draws the cutaway of that housing for the chip scene: the mounting plate, a small
22	 * board whose thin traces carry readings in from the four water pods and the four weather sensors to
23	 * one small chip marked TinyML, the battery and two backup storage cans, the radio can whose coax
24	 * runs to the antenna, and the amber risk lamp. No network cable leaves the box. It also draws the
25	 * pinned paper tags that carry the film's few words.
26	 *
27	 * Light: late afternoon storm light low from the upper left, cool sky fill from the right, a long
28	 * soft shadow falling right. Nothing is symmetric: the post leans a little, the housing hangs off
29	 * level, the conduit sags, the pods step left and right, the antenna is bent, the panel corner is
30	 * chipped and there is a rust drip under the clamp. Maintained but worn.
31	 *
32	 * Disclosed illustration of the described prototype. No logo, brand, real site or measured value.
33	 * Pure function of its props; the episode drives every prop from the film frame clock.
34	 */
35	
36	export type Pal = Record<'background'|'midground'|'foreground'|'ink'|'paper'|'hero'|'accent', string>;
37	export type Pt = [number, number];
38	const clamp = (v: number) => Math.min(1, Math.max(0, v));
39	const lerp = (a: number, b: number, p: number) => a + (b - a) * p;
40	/** A seeded generator: the same seed draws the same spangle on every frame and every render. */
41	function rng(seed: number) {
42	 let a = seed >>> 0;
43	 return () => {a = (a + 0x6D2B79F5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296;};
44	}
45	
46	/** Galvanized steel and enclosure plastic under a low warm sun from the upper left. */
