5	/**
6	 * StreetHubSupport, the fresh authored support group for the 2026-10-15 edition.
7	 *
8	 * The San Antonio world around the flood station and the places its warning goes. A wet asphalt
9	 * street with a hand-cut limestone curb and a dark gutter, a St. Augustine lawn with dormant brown
10	 * patches, a chain link fence whose second post carries an orange ankle-high spray mark and leans a
11	 * little, a live oak edge with low spreading limbs, furrowed bark and grey ball moss, and the corner
12	 * of a painted bungalow porch with two steps and a rail where a worn phone lies screen up. Brown
13	 * flood water with a hand-drawn, lobed edge, drifting leaves and foam. A far cell tower and the
14	 * dashed outline of a central server, which both stay unconnected. A short street of bungalows, the
15	 * open country beyond it, thin radio rings with a half-mile tag and a five-mile tag, a small
16	 * limestone hub building with a rooftop mast, the hub desk with its monitor and a responder's
17	 * sleeved forearm in a dark work glove, the dashboard map with station dots, shaded flood paths and
18	 * dashed higher-risk outlines, the validation card, the blank field result card and the paper street
19	 * map with no pin on it.
20	 *
21	 * Light matches the hero: low warm storm light from the upper left, cool fill from the right, long
22	 * soft shadows falling right. Nothing is symmetric: the fence post leans, the curb blocks differ, the
23	 * oak is lopsided, the phone case is scuffed on one corner. No logos, names, faces, real streets,
24	 * addresses, agencies or measured values; the only figure drawn is the university's own reported
25	 * validation accuracy, passed in by the episode from its claim.
26	 *
27	 * Pure function of its props; the episode drives every prop from the film frame clock.
28	 */
29	
30	type Pal = Record<'background'|'midground'|'foreground'|'ink'|'paper'|'hero'|'accent', string>;
31	type Pt = [number, number];
32	const clamp = (v: number) => Math.min(1, Math.max(0, v));
33	const lerp = (a: number, b: number, p: number) => a + (b - a) * p;
34	const ease = (p: number) => {const q = clamp(p); return q * q * q * (10 + q * (-15 + 6 * q));};
35	/** A seeded generator: the same seed draws the same lawn, oak and debris on every frame. */
36	function rng(seed: number) {
37	 let a = seed >>> 0;
38	 return () => {a = (a + 0x6D2B79F5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296;};
39	}
