370	/** The dashboard map drawn in screen units w by h: streets, a creek, station dots, flood paths and zones. */
371	const Dashboard: React.FC<{w: number; h: number; dots?: number; paths?: number; zones?: number; t?: number; pal: Pal; header?: boolean}> =
372	 ({w, h, dots = 0, paths = 0, zones = 0, t = 0, pal, header = true}) => {
373	 const id = useUid('sadb');
374	 const r = rng(21);
375	 const creek: Pt[] = [[-.05, .62], [.18, .58], [.32, .66], [.5, .6], [.64, .7], [.82, .64], [1.05, .74]].map(([x, y]) => [x * w, y * h] as Pt);
376	 const sx = Array.from({length: 7}, (_, i) => w * (.08 + i * .14 + (r() - .5) * .03));
377	 const sy = Array.from({length: 5}, (_, i) => h * (.2 + i * .17 + (r() - .5) * .03));
378	 const stations: Pt[] = [[.16, .56], [.36, .64], [.55, .57], [.72, .67], [.86, .62], [.46, .36]].map(([x, y]) => [x * w, y * h] as Pt);
379	 const spread = ease(paths);
380	 // flood paths: shaded lobes that grow out from the creek along the low streets, from the first dots
381	 const lobes: [Pt, number, number, number][] = [[[.2, .6], .16, .07, 0], [[.38, .66], .14, .08, .1], [[.56, .6], .18, .09, .2], [[.74, .68], .15, .07, .3], [[.47, .5], .07, .12, .4], [[.9, .7], .12, .06, .45]]
382	  .map(([c, rx, ry, delay]) => [[(c as Pt)[0] * w, (c as Pt)[1] * h] as Pt, (rx as number) * w, (ry as number) * h, delay as number]);
383	 const zonesBox: [number, number, number, number, number][] = [[.1, .5, .24, .2, -3], [.48, .5, .2, .24, 2], [.66, .58, .24, .18, -1]];
384	 return <g data-part="dashboard-map">
385	  <defs><linearGradient id={id} x1="0" y1="0" x2="1" y2="1">
386	   <stop offset="0" stopColor={SA.slateLit}/><stop offset="1" stopColor={SA.slate}/>
387	  </linearGradient>
388	  <radialGradient id={id + 'f'} cx=".5" cy=".5" r=".5"><stop offset="0" stopColor={SA.water} stopOpacity={.95}/><stop offset=".7" stopColor="#9A6A36" stopOpacity={.7}/><stop offset="1" stopColor="#C88A3A" stopOpacity={0}/></radialGradient></defs>
389	  <rect x={0} y={0} width={w} height={h} fill={`url(#${id})`}/>
390	  {/* blocks, streets and the creek */}
391	  {sx.map((x, i) => <path key={'x' + i} d={`M${x} ${h * .1}L${x + (i % 2 ? 10 : -8)} ${h}`} stroke={SA.street} strokeWidth={i === 3 ? 7 : 4} opacity={.7}/>)}
392	  {sy.map((y, i) => <path key={'y' + i} d={`M0 ${y}L${w} ${y + (i % 2 ? 12 : -6)}`} stroke={SA.street} strokeWidth={i === 2 ? 7 : 4} opacity={.7}/>)}
393	  <path d={'M' + creek.map(p => p.join(' ')).join('L')} stroke={SA.creek} strokeWidth={12} fill="none" strokeLinejoin="round" opacity={.9}/>
394	  {lobes.map(([c, rx, ry, delay], i) => {const g = clamp((spread - delay) / (1 - delay)); return g > 0 &&
395	   <ellipse key={'f' + i} cx={c[0]} cy={c[1]} rx={rx * g} ry={ry * g} fill={`url(#${id}f)`} opacity={.9}/>;})}
396	  {zones > 0 && zonesBox.map(([x, y, bw, bh, rot], i) => {const g = clamp(zones * 1.5 - i * .25);
397	   return g > 0 && <rect key={'z' + i} x={x * w} y={y * h} width={bw * w} height={bh * h} rx={14} fill="none" stroke={pal.accent}
398	    strokeWidth={5} strokeDasharray={`${20 * g} ${14}`} transform={`rotate(${rot} ${(x + bw / 2) * w} ${(y + bh / 2) * h})`} opacity={g}/>;})}
399	  {stations.map(([x, y], i) => {const g = clamp(dots * 1.6 - i * .12); return g > 0 && <g key={'s' + i} transform={`translate(${x} ${y}) scale(${ease(g)})`}>
400	   <circle cx={0} cy={0} r={22 * (1 + .2 * Math.sin(t * 3 + i))} fill={pal.accent} opacity={.18}/>
401	   <circle cx={0} cy={0} r={11} fill="#F5F0E3" stroke={pal.accent} strokeWidth={4}/>
402	  </g>;})}
403	  {header && <g>
404	   <rect x={0} y={0} width={w} height={h * .1} fill="#121A1D" opacity={.85}/>
405	   <text x={w * .04} y={h * .068} fontFamily={FONT.body} fontSize={h * .05} fontWeight={800} fill="#E9E4D6">Flood spread map</text>
406	   {zones > 0 && <g opacity={clamp(zones * 2)}>
407	    <rect x={w * .64} y={h * .028} width={w * .045} height={h * .045} rx={4} fill="none" stroke={pal.accent} strokeWidth={3} strokeDasharray="8 5"/>
408	    <text x={w * .7} y={h * .066} fontFamily={FONT.body} fontSize={h * .042} fontWeight={700} fill="#E9E4D6">Higher risk</text>
409	   </g>}
410	  </g>}
411	 </g>;
