414	/** The overhead radio map: a city grid upper left, open country lower right, the station and the hub. */
415	const RadioMap: React.FC<{w: number; h: number; ring?: number; half?: number; five?: number; hub?: number; pal: Pal; station: Pt; hubAt: Pt}> =
416	 ({w, h, ring = 0, half = 0, five = 0, hub = 0, pal, station, hubAt}) => {
417	 const id = useUid('sarm');
418	 const r = rng(31);
419	 const reach = Math.hypot(hubAt[0] - station[0], hubAt[1] - station[1]);
420	 const halfR = reach * .2;
421	 return <g data-part="radio-map">
422	  <defs><clipPath id={id}><rect x={0} y={0} width={w} height={h} rx={18}/></clipPath></defs>
423	  <rect x={6} y={10} width={w} height={h} rx={18} fill="#1E1A16" opacity={.2}/>
424	  <rect x={0} y={0} width={w} height={h} rx={18} fill="#E9E2CF" stroke={pal.ink} strokeWidth={3}/>
425	  <g clipPath={`url(#${id})`}>
426	   {/* open country: field strips and a section road */}
427	   {Array.from({length: 9}, (_, i) => <path key={'f' + i} d={`M${w * .35 + i * 70} ${h}L${w * .5 + i * 90} ${h * .3}`} stroke="#C9C09A" strokeWidth={30} opacity={.35}/>)}
428	   <path d={`M0 ${h * .55}Q${w * .5} ${h * .5} ${w} ${h * .62}`} stroke="#B9AE8E" strokeWidth={10} fill="none"/>
429	   {/* the city grid around the station */}
430	   {Array.from({length: 8}, (_, i) => <path key={'gx' + i} d={`M${station[0] - 260 + i * 70 + r() * 8} ${station[1] - 300}V${station[1] + 280}`} stroke="#B3AA92" strokeWidth={6}/>)}
431	   {Array.from({length: 9}, (_, i) => <path key={'gy' + i} d={`M${station[0] - 280} ${station[1] - 300 + i * 66 + r() * 8}H${station[0] + 250}`} stroke="#B3AA92" strokeWidth={6}/>)}
432	   {Array.from({length: 18}, (_, i) => <rect key={'b' + i} x={station[0] - 252 + (i % 6) * 70 + 8} y={station[1] - 290 + Math.floor(i / 6) * 132 + 10} width={50} height={40} fill="#D3C8AE" opacity={.8}/>)}
433	   <path d={`M${-20} ${h * .2}Q${w * .3} ${h * .34} ${w * .45} ${h * .3}T${w + 20} ${h * .46}`} stroke={SA.creek} strokeWidth={9} fill="none" opacity={.8}/>
434	   {/* the rings */}
435	   {ring > 0 && [0, 1, 2].map(k => {const u = clamp(ring * 1.3 - k * .15); return u > 0 && u < 1 &&
436	    <circle key={k} cx={station[0]} cy={station[1]} r={reach * 1.05 * u} fill="none" stroke={pal.accent} strokeWidth={6 - 3 * u} opacity={.9 * (1 - .6 * u)}/>;})}
437	   {half > 0 && <circle cx={station[0]} cy={station[1]} r={halfR} fill="none" stroke={pal.ink} strokeWidth={3} strokeDasharray="10 8" opacity={half}/>}
438	   {five > 0 && <circle cx={station[0]} cy={station[1]} r={reach} fill="none" stroke={pal.ink} strokeWidth={3} strokeDasharray="14 10" opacity={five}/>}
439	  </g>
440	  {/* the station dot and the hub */}
441	  <circle cx={station[0]} cy={station[1]} r={16} fill={pal.paper} stroke={pal.ink} strokeWidth={4}/>
442	  <circle cx={station[0]} cy={station[1]} r={7} fill={pal.accent}/>
443	  <g transform={`translate(${hubAt[0]} ${hubAt[1]})`}>
444	   {hub > 0 && <circle cx={0} cy={0} r={30 + 30 * hub} fill={pal.accent} opacity={.3 * hub}/>}
445	   <rect x={-22} y={-16} width={44} height={32} rx={4} fill={pal.paper} stroke={pal.ink} strokeWidth={4}/>
446	   <path d="M-8 -16V-40M-8 -40L-2 -50" stroke={pal.ink} strokeWidth={4}/>
447	  </g>
448	 </g>;
