2	export type DirectedScene = {
3	  id: string; start_s: number; duration_s: number;
4	  visual_events?: {id?: string; at_s: number; duration_s?: number; item_ids?: string[];
5	    motion?: {curve: 'smoothstep'|'linear'|'travel'|'contact'|'landing'; anticipation?: number; settle?: number;free_prop_reason?:string}}[];
6	};
7	export type ActionWindow = {start: number; end: number; scene: string; itemIds: string[];
8	  motion?: NonNullable<DirectedScene['visual_events']>[number]['motion']};
9	export type NarrationPicture = {version:'narration-picture-v1';timing_mode:string;
10	  clauses:{id:string;text:string;scene_id:string;subject_ids:string[];action_id:string;
11	    start_s:number;end_s:number;cue_ids:string[];word_range:[number,number];event_ids:string[];claim_ids:string[]}[]};
12	/** One shared acoustic clock for picture, performance and their exact-film review. */
13	export function requireNarration(board:{narration_picture?:NarrationPicture},id:string){
14	 const plan=board.narration_picture;
15	 if(!plan||plan.version!=='narration-picture-v1')throw new Error('Missing narration-picture contract');
16	 const rows=plan.clauses.filter(c=>c.id===id);
17	 if(rows.length!==1)throw new Error('Missing or duplicate narration clause '+id);
18	 const row=rows[0];
19	 if(!Number.isFinite(row.start_s)||!Number.isFinite(row.end_s)||row.start_s<0||row.end_s<=row.start_s
20	    ||!row.subject_ids.length||!row.action_id)throw new Error('Invalid narration clause '+id);
21	 return {start:row.start_s,end:row.end_s,subjectIds:row.subject_ids,actionId:row.action_id};
22	}
23	export function actionWindows(scenes: DirectedScene[]): Record<string, ActionWindow> {
24	  const windows: Record<string, ActionWindow> = Object.create(null);
25	  for (const scene of scenes) for (const event of scene.visual_events ?? []) {
26	    if (!event.id) continue;
27	    if (windows[event.id]) throw new Error('Duplicate action id '+event.id);
28	    const start = scene.start_s + event.at_s;
29	    const duration = event.duration_s ?? .6;
30	    if (!Number.isFinite(start) || !Number.isFinite(duration) || duration<=0 ||
31	        event.at_s<0 || event.at_s+duration>scene.duration_s+.001) {
32	      throw new Error('Action '+event.id+' falls outside its scene');
33	    }
34	    windows[event.id]={start,end:start+duration,scene:scene.id,itemIds:event.item_ids??[],
35	      ...(event.motion ? {motion:event.motion} : {})};
36	  }
37	  return windows;
38	}
39	export function requireAction(windows: Record<string, ActionWindow>, id: string): ActionWindow {
40	  const found=windows[id];
41	  if (!found) throw new Error('Missing board action '+id);
42	  return found;
43	}
44	export function actionProgress(window: ActionWindow, storyTime: number): number {
45	  const p=Math.max(0,Math.min(1,(storyTime-window.start)/(window.end-window.start)));
46	  if (!window.motion) return p*p*(3-2*p);
47	  const {curve,anticipation=0,settle=0}=window.motion;
48	  if (!['smoothstep','linear','travel','contact','landing'].includes(curve) ||
49	      !Number.isFinite(anticipation) || anticipation<0 || anticipation>.3 ||
50	      !Number.isFinite(settle) || settle<0 || settle>.4) {
51	    throw new Error('Invalid directed event motion');
52	  }
53	  if (p===0 || p===1) return p;
54	  const q=Math.max(0,Math.min(1,(p-anticipation)/(1-anticipation-settle)));
55	  if (curve==='linear') return q;
56	  // Both constrained curves enter and leave a hold with zero velocity and
57	  // acceleration. The old contact ease jumped straight to maximum speed;
58	  // the two-piece travel curve changed acceleration abruptly at its midpoint.
59	  if (curve==='contact') return q*q*q*(20+q*(-45+q*(36-10*q)));
60	  if (curve==='travel') return q*q*q*(10+q*(-15+6*q));
61	  if (curve==='landing') {
62	    // A small overshoot is opt-in for free props, never for a constrained contact.
63	    const base=1-Math.pow(1-q,3);
64	    const bounce=q>.6?.035*Math.sin((q-.6)/.4*Math.PI)*Math.exp(-(q-.6)*2):0;
65	    return q===0 || q===1 ? q : base+bounce;
66	  }
67	  return q*q*(3-2*q);
68	}
69	export function directedValue(window: ActionWindow, storyTime: number, from: number, to: number) {
70	  return from+(to-from)*actionProgress(window,storyTime);
71	}
