73	/** Explicitly join adjacent stages of one stroke without restarting its speed.
74	 * Interior authored rests must never disappear into a continuous movement. */
75	export function joinedActionWindow(windows: Record<string,ActionWindow>, ids: string[]): ActionWindow {
76	  if(ids.length<2 || new Set(ids).size!==ids.length)throw new Error('Joined action needs distinct consecutive events');
77	  const rows=ids.map(id=>requireAction(windows,id)),first=rows[0],last=rows[rows.length-1];
78	  const curve=first.motion?.curve;
79	  if(curve!=='travel' && curve!=='contact')throw new Error('Joined action needs a constrained continuous curve');
80	  for(let i=0;i<rows.length;i++){
81	    const row=rows[i];
82	    if(row.scene!==first.scene || row.motion?.curve!==curve ||
83	       (i>0 && (Math.abs(row.start-rows[i-1].end)>.001 || (row.motion.anticipation??0)!==0)) ||
84	       (i<rows.length-1 && (row.motion.settle??0)!==0)) {
85	      throw new Error('Joined action cannot cross a scene, gap, curve change or interior hold');
86	    }
87	  }
88	  const duration=last.end-first.start;
89	  return {start:first.start,end:last.end,scene:first.scene,itemIds:[...new Set(rows.flatMap(r=>r.itemIds))],
90	    motion:{curve,anticipation:(first.motion?.anticipation??0)*(first.end-first.start)/duration,
91	      settle:(last.motion?.settle??0)*(last.end-last.start)/duration}};
92	}
