308	 const inputs: {from: Pt; via: Pt[]; kind: 'pod' | 'weather'; k: number}[] = [
309	  ...[0, 1, 2, 3].map(k => ({from: [-262, 160 - k * 36] as Pt, via: [[-150, 160 - k * 36] as Pt, [-40, 70 - k * 14] as Pt], kind: 'pod' as const, k})),
