313	 const along = (pts: Pt[], u: number): Pt => {
314	  const seg = pts.slice(1).map((q, i) => Math.hypot(q[0] - pts[i][0], q[1] - pts[i][1]));
315	  let d = clamp(u) * seg.reduce((a, b) => a + b, 0);
