222	/** Brown flood water: a far surface line with live ripples and a lobed, hand-drawn near edge. */
223	const Water: React.FC<{x0: number; x1: number; y: number; depth: number; t: number; seed?: number; edge?: 'lobed' | 'straight'; opacity?: number}> =
224	 ({x0, x1, y, depth, t, seed = 11, edge = 'lobed', opacity = .92}) => {
225	 const id = useUid('saw');
226	 const r = rng(seed);
227	 const n = 28;
228	 const phases = Array.from({length: n + 1}, () => r() * 6.28);
229	 const lobes = Array.from({length: n + 1}, () => r());
230	 const top = Array.from({length: n + 1}, (_, i) => {const x = lerp(x0, x1, i / n); return [x, y + 2.2 * Math.sin(t * 2.1 + phases[i]) + 1.4 * Math.sin(x * .05 + t * 1.3)] as Pt;});
231	 const bot = Array.from({length: n + 1}, (_, i) => {const x = lerp(x1, x0, i / n);
232	  const k = n - i; const lobe = edge === 'lobed' ? depth * (.08 * Math.sin(k * 1.7 + 1) + .1 * (lobes[k] - .5)) + 2 * Math.sin(t * 1.4 + phases[k]) : 0;
233	  return [x, y + depth + lobe] as Pt;});
234	 const d = 'M' + [...top, ...bot].map(p => p.map(v => v.toFixed(1)).join(' ')).join('L') + 'Z';
235	 const debris = Array.from({length: 7}, () => [r(), r(), r()]);
