68	export function plateFor(scene:PlaceScene):Plate{
69	 const inRegion=Object.values(M.plates).filter(p=>p.region===scene.region).sort((a,b)=>a.id.localeCompare(b.id));
70	 if(!inRegion.length)throw new Error('No place plate for region '+scene.region+'; bake one with scripts/place_bake.py');
71	 const county=countyName(scene.county);
72	 if(scene.place_plate){
73	  const p=M.plates[scene.place_plate];
74	  if(!p||p.region!==scene.region)throw new Error('Place plate '+scene.place_plate+' is not a '+scene.region+' plate');
75	  const scope=[...(p.counties??[]),...(p.also??[])].map(countyName);
76	  if(scope.length&&!scope.includes(county))throw new Error('Place plate '+p.id+' is not for '+scene.county+' County');
77	  return p;
78	 }
79	 const own=inRegion.find(p=>(p.counties??[]).map(countyName).includes(county));
80	 const base=inRegion.find(p=>!p.counties?.length&&!p.also?.length);
81	 if(!own&&!base)throw new Error('Region '+scene.region+' has no plate of its own');
82	 return (own??base)!;
83	}
