138	type Framing=FilmShot['framing'];
139	const ZOOM:Record<Framing,number>={wide:1,split:1.04,medium:1.08,close:1.18,detail:1.3,overhead:1};
140	const DEFOCUS:Record<Framing,number>={wide:0,split:0,medium:0,close:1.5,detail:3,overhead:0};
141	/* THE WINDOW starts below the title band, which both episodes set from y 250 to 370, so no mullion
142	 * ever crosses a title. A wide shot's title box sits lower, to y 419 in the October 7th film, and two
143	 * blind graders found the window's top rail running through it, so a wide window starts at 440.
144	 * Nearer framings see more of it and less sharply, as a lens focused on the subject would. */
145	type Window={x:number;y:number;w:number;h:number;blur:number};
146	const WINDOW:Record<Framing,Window>={
147	 wide:{x:96,y:440,w:888,h:540,blur:1.5},split:{x:40,y:410,w:1000,h:640,blur:3},
148	 medium:{x:40,y:410,w:1000,h:640,blur:3},close:{x:-40,y:400,w:1160,h:720,blur:6},
149	 detail:{x:-80,y:400,w:1240,h:760,blur:9},overhead:{x:0,y:0,w:0,h:0,blur:0}};
150	const HORIZON_IN_WINDOW=.55;   // eye height in a window from sill to head
151	/* SEEN FROM A ROOM EXPOSED FOR THE ROOM, the outside is bright and soft. That is how a camera sees a
152	 * window, and it is what keeps an episode's unboxed type legible over it: on October 8th the fly film
153	 * set plain red and teal text from y 400 to 1245, and over the marsh at full contrast the red read
