169	type Registry={episodes:Record<string,{wall_views?:string[];wash_views?:string[]}>};
170	const listed=(key:'wall_views'|'wash_views')=>(board:{film_direction?:{episode?:string}},view:string):boolean=>{
171	 const ep=board.film_direction?.episode;
172	 return !!ep&&((registry as unknown as Registry).episodes[ep]?.[key]??[]).includes(view);
173	};
174	export const wallView=listed('wall_views');
175	/** A VIEW IN THE WASH. A labelled comparison set out across the frame, two flies on their own ground
