189	/** The plate's layers, each placed by its own matrix F (plate pixels to the container's pixels). */
190	const Layers:React.FC<{plate:Plate;frame:(depth:number|'ground'|'sky')=>M3;probe:boolean}>=({plate,frame,probe})=>{
191	 const one=(key:string,L:Layer,F:M3,w:number,h:number)=><Img key={key} src={staticFile(L.file)} data-place-layer={key}
