202	export const PlaceStage:React.FC<{board:DispatchProps;scene:Scene;shot:FilmShot;time_s:number;children:React.ReactNode}>=
203	 ({board,scene,shot,time_s,children})=>{
204	 const art=useArtDirection();
205	 const b=board as DispatchProps&PlaceBoard;
206	 if(!placeActive(b))return <>{children}</>;
