208	 const framing=shot.framing;
209	 const mode=framing==='overhead'?'overhead':wallView(b,shot.view)?'wall':scene.interior?'interior':'exterior';
210	 const probe=b.__placeProbe===true;
211	 const u=(time_s-scene.start_s)/scene.duration_s;
212	 const move=mode==='exterior'?placeMove(plate,scene.camera_strategy,u):{dolly:0,truck:0,rise:0};
213	 const zoom=ZOOM[framing];
214	 const cam=plate.camera;
215	 const wall=art?.palette;
216	 let world:React.ReactNode;
217	 let info:PlaceInfo={plate,mode,framing,move,zoom};
218	 if(mode==='exterior'){
219	  const Z=scaleAbout(zoom,cam.cx,cam.cy),toFrame=translate(-OX,-OY);
220	  const frame=(d:number|'ground'|'sky')=>mul(toFrame,mul(Z,d==='sky'?translate(0,0):d==='ground'?groundHomography(cam,move):cardMatrix(cam,d,move)));
