224	 }else if(mode==='interior'&&(BOKEH_BLUR[framing]||washView(b,shot.view))){
225	  const blur=BOKEH_BLUR[framing]??BOKEH_BLUR.close;
226	  const paper=wall?.paper??rgb(plate.sky_rgb),F=mul(translate(-OX,-OY),scaleAbout(BOKEH_ZOOM,cam.cx,cam.cy));
