228	   <div style={{position:'absolute',inset:0,filter:probe?undefined:`blur(${blur}px) ${WINDOW_GRADE}`}}>
229	    <Layers plate={plate} frame={()=>F} probe={probe}/>
230	   </div>
231	   {!probe&&<div style={{position:'absolute',inset:0,background:paper,opacity:BOKEH_HAZE}}/>}
232	  </div>;
