238	  info={...info,window:W};
239	  const paper=wall?.paper??rgb(plate.sky_rgb),back=wall?.background??rgb(plate.ground_rgb),ink=wall?.ink??'#2a2622';
240	  const keyX=art?.lighting.key.position[0]??1;
241	  const mx=[W.w/3,2*W.w/3];   // mullions only: a transom across the window would run along a line of text
242	  world=<>
243	   <div data-place-window style={{position:'absolute',left:W.x,top:W.y,width:W.w,height:W.h,overflow:'hidden'}}>
244	    <div style={{position:'absolute',inset:0,filter:probe?undefined:`blur(${W.blur}px) ${WINDOW_GRADE}`}}>
245	     <Layers plate={plate} frame={()=>P} probe={probe}/>
246	    </div>
247	   </div>
248	   <svg width={FW} height={FH} viewBox={`0 0 ${FW} ${FH}`} style={{position:'absolute',inset:0}}>
249	    <defs>
250	     <linearGradient id="place-wall" x1={keyX<0?'0':'1'} y1="0" x2={keyX<0?'1':'0'} y2="1">
251	      <stop offset="0" stopColor={paper}/><stop offset="1" stopColor={back}/>
252	     </linearGradient>
253	     <radialGradient id="place-spill" gradientUnits="userSpaceOnUse" cx={W.x+W.w/2} cy={W.y+W.h*.45} r={W.w*.85}>
