255	     </radialGradient>
256	     <linearGradient id="place-glass" x1="0" y1="0" x2="1" y2="1">
257	      <stop offset="0" stopColor="#fff" stopOpacity={0}/><stop offset=".42" stopColor="#fff" stopOpacity={0}/>
258	      <stop offset=".5" stopColor="#fff" stopOpacity={.09}/><stop offset=".58" stopColor="#fff" stopOpacity={0}/>
259	     </linearGradient>
260	    </defs>
261	    {/* the wall, and the window's light falling on it, never on the glass */}
262	    {['url(#place-wall)','url(#place-spill)'].map(fill=><path key={fill} fillRule="evenodd" fill={fill}
263	     d={`M0 0H${FW}V${FH}H0Z M${W.x} ${W.y}V${W.y+W.h}H${W.x+W.w}V${W.y}Z`}/>)}
264	    {!probe&&<rect x={W.x} y={W.y} width={W.w} height={W.h} fill={paper} opacity={WINDOW_HAZE}/>}
265	    {!probe&&<rect x={W.x} y={W.y} width={W.w} height={W.h} fill="url(#place-glass)"/>}
266	    {/* a light frame: a dark one crossed every thin line and glass edge in front of it */}
267	    <g stroke={ink} fill="none">
268	     <rect x={W.x} y={W.y} width={W.w} height={W.h} strokeWidth={12} strokeOpacity={.42}/>
269	     {mx.map((x,i)=><path key={i} d={`M${W.x+x} ${W.y}V${W.y+W.h}`} strokeWidth={6} strokeOpacity={.3}/>)}
270	    </g>
271	    <rect x={W.x-26} y={W.y+W.h+6} width={W.w+52} height={20} rx={3} fill={paper} stroke={ink} strokeOpacity={.5} strokeWidth={3}/>
272	   </svg>
273	  </>;
274	 }else{
275	  const keyX=art?.lighting.key.position[0]??1;
276	  world=<svg width={FW} height={FH} viewBox={`0 0 ${FW} ${FH}`} style={{position:'absolute',inset:0}}>
