10	export const MODERN_EFFECTIVE_DATE='2026-10-08';
11	export function assertFilmRoute(board:Pick<DispatchProps,'date'|'cinematic_template'|'film_direction'>){
12	  if ((/^\d{4}-\d{2}-\d{2}/.test(board.date??'')&&(board.date??'')>=MODERN_EFFECTIVE_DATE)||board.film_direction){
13	    if(board.cinematic_template!=='directed-film-v2'||board.film_direction?.version!=='directed-film-v2'){
14	      throw new Error('Current production requires directed-film-v2. Legacy episodes are historical only.');
15	    }
16	    if(!modernEpisodes[board.film_direction.episode])throw new Error('Unregistered modern film episode');
17	  }
18	}
19	type FrameInterval={shot:FilmShot;start:number;end:number};
20	const frameIntervals=new WeakMap<FilmDirection,Map<number,FrameInterval[]>>();
21	export function filmShotAt(plan:FilmDirection,time:number,fps=30):FilmShot{
22	 if(!Number.isFinite(fps)||fps<=0||!Number.isFinite(time))throw new Error('Invalid modern frame clock');
23	 let byRate=frameIntervals.get(plan);
24	 if(!byRate){byRate=new Map();frameIntervals.set(plan,byRate);}
25	 let intervals=byRate.get(fps);
26	 if(!intervals){
27	  intervals=plan.shots.map(shot=>{
28	   const start=Math.round(shot.start_s*fps),end=Math.round((shot.start_s+shot.duration_s)*fps);
29	   if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start)throw new Error('Invalid modern native shot interval');
30	   return {shot,start,end};
31	  });
32	  byRate.set(fps,intervals);
33	 }
34	 const frame=Math.floor(time*fps+1e-7);
35	 const matches=intervals.filter(row=>frame>=row.start&&frame<row.end);
36	 if(matches.length!==1)throw new Error(matches.length?'Modern shot timeline has overlapping native frames':'Modern shot timeline has an uncovered frame');
37	 return matches[0].shot;
38	}
39	export const DirectedFilm:React.FC<DispatchProps>=(board)=>{
40	  assertFilmRoute(board);
41	  const {fps}=useVideoConfig(),frame=useCurrentFrame(),time=frame/fps;
42	  const plan=board.film_direction!;
43	  const end=Math.max(...board.scenes.map(s=>s.start_s+s.duration_s));
44	  if(frame>=Math.round(end*fps))return <Sequence from={Math.round(end*fps)} durationInFrames={Math.round((board.credits_s??5)*fps)}><CreditsCard text={board.credits??''}/></Sequence>;
45	  const shot=filmShotAt(plan,time,fps);
