1	import React from 'react';
2	import {Easing,interpolate} from 'remotion';
3	import map from './texasCounties.json';
4	
5	/** WHERE IN TEXAS, for a few seconds near the start of a current film (October 9th, 2026).
6	 *
7	 * A small card in the top right draws the state's outline, fills the story's county and pins it.
8	 * The map is computed from the committed Census county file by scripts/county_map.py, never drawn by
9	 * hand. It carries no words: the county is a board field that no claim stands behind, so naming it
10	 * on screen would put an unsourced fact in the film, and the narration names the place anyway.
11	 *
12	 * THE TIMING is the map-explainer rule vetted from the Remotion skills (map-explainer-architecture.md):
13	 * each phase runs a fixed time from its own start rather than a slice of a reveal, so a long border
14	 * never flashes by. The border draws in BORDER_S on the house draw curve, the county fills in FILL_S
15	 * with its opacity overshooting to 1.25 times its rest before settling, and the pin lands in PIN_S,
16	 * the rule's label phase. It starts after the first frame's decision, holds, and leaves.
17	 *
18	 * Its card sits inside the feed's safe area (lib/safearea.ts reserves the right 15 percent and the
19	 * bottom 26 percent) and above both episodes' title band, which starts at y 279. */
20	export const LOCATOR_START_S=2.0,BORDER_S=2.5,FILL_S=1.0,PIN_S=0.7,HOLD_S=1.4,FADE_S=0.5;
21	export const LOCATOR_END_S=LOCATOR_START_S+BORDER_S+FILL_S+PIN_S+HOLD_S+FADE_S;
22	const CARD={x:704,y:80,w:200,h:190,pad:14},FILL_REST=.8;   // 1.25 times the rest is full opacity
23	const DRAW=Easing.bezier(.645,.045,.355,1);
24	type CountyMap={width:number;height:number;outline:string;islands:string;counties:Record<string,{fips:string;d:string;label:[number,number]}>};
25	const MAP=map as unknown as CountyMap;
26	
27	/** A county as the shipping gate compares it (county_regions.normalise): no trailing County in any case,
28	 * no spaces, dots or apostrophes, lower case. So a county the gate accepts is always on this map. Case
29	 * alone was not enough: the gate read "De Witt" as DeWitt, and this threw mid-render (Codex, PR 117). */
30	export const countyName=(c?:string)=>(c??'').trim().replace(/\s+county$/i,'').toLowerCase().replace(/[ .']/g,'');
31	
32	export function countyKey(county:string):string{
33	 const want=countyName(county);
34	 const key=Object.keys(MAP.counties).find(k=>countyName(k)===want);
35	 if(!key)throw new Error('County '+county+' is not on the Texas county map');
36	 return key;
37	}
38	const clamp=(v:number)=>Math.max(0,Math.min(1,v));
39	
40	export const CountyLocator:React.FC<{county:string;time_s:number;ink:string;paper:string;accent:string}>=
41	 ({county,time_s,ink,paper,accent})=>{
42	 const t=time_s-LOCATOR_START_S;
43	 if(t<0||time_s>=LOCATOR_END_S)return null;
44	 const c=MAP.counties[countyKey(county)];
45	 const border=DRAW(clamp(t/BORDER_S));
46	 const f=clamp((t-BORDER_S)/FILL_S);
47	 // the fill's opacity overshoots to 1.25 times its rest, then settles
48	 const fill=interpolate(f,[0,.6,1],[0,FILL_REST*1.25,FILL_REST],{extrapolateLeft:'clamp',extrapolateRight:'clamp'});
49	 const pin=Easing.out(Easing.back(1.6))(clamp((t-BORDER_S-FILL_S)/PIN_S));
50	 const out=clamp((time_s-(LOCATOR_END_S-FADE_S))/FADE_S);
51	 const card=clamp(t/.3)*(1-out);
52	 const inner=CARD.w-2*CARD.pad,k=Math.min(inner/MAP.width,(CARD.h-2*CARD.pad)/MAP.height);
53	 const ox=CARD.x+(CARD.w-MAP.width*k)/2,oy=CARD.y+(CARD.h-MAP.height*k)/2;
54	 const [lx,ly]=c.label;
55	 return <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position:'absolute',inset:0}}
56	  data-county-locator={countyKey(county)} opacity={card}>
57	  <rect x={CARD.x+5} y={CARD.y+7} width={CARD.w} height={CARD.h} rx={12} fill={ink} opacity={.16}/>
58	  <rect x={CARD.x} y={CARD.y} width={CARD.w} height={CARD.h} rx={12} fill={paper} stroke={ink} strokeWidth={3}/>
59	  <g transform={`translate(${ox} ${oy}) scale(${k})`}>
60	   {/* the whole state, faint, from the first frame, so a still caught mid-draw is a map being marked */}
61	   <path d={MAP.outline} fill="none" stroke={ink} strokeWidth={2.2/k} strokeLinejoin="round" opacity={.16}/>
62	   <path d={c.d} fill={accent} opacity={fill}/>
63	   {MAP.islands&&<path d={MAP.islands} fill="none" stroke={ink} strokeWidth={1.4/k} opacity={border}/>}
64	   <path d={MAP.outline} fill="none" stroke={ink} strokeWidth={2.6/k} strokeLinejoin="round"
65	    pathLength={1} strokeDasharray={1} strokeDashoffset={1-border}/>
66	   <g transform={`translate(${lx} ${ly}) scale(${pin/k})`} opacity={clamp(pin*2)}>
67	    <circle r={12} fill="none" stroke={ink} strokeWidth={3}/>
68	   </g>
69	  </g>
70	 </svg>;
71	};
