1	// =============================================================================
2	// TYPE — how wide a string is, and where to break it.
3	//
4	// WHY THIS FILE EXISTS
5	//
6	// `HandsetAlert` drew "FLASH FLOOD WARNING" at font size 9 inside a panel 70 units
7	// wide, and the string is about 12.3 ems, which is 111 units. It ran a third of the
8	// way out of the phone, across the lock screen and off the glass, on the one beat
9	// this show has about an emergency message. It shipped that way through every gate
10	// the repo has, because no gate reads type.
11	//
12	// THE HARDER HALF, and it is the reason this is a file rather than a shorter string.
13	// `headline` and `body` are PROPS. Shortening the one string this repo passes today
14	// fixes today and nothing else: the next caller writes a longer warning and the
15	// panel overflows again with no warning of its own. A drawing that accepts text has
16	// to be able to set that text.
17	//
18	// HOW THE WIDTHS WERE GOT. Measured, not guessed, and not from a font table either.
19	// A probe rendered real strings through the real renderer at font size 30, in BOTH
20	// shipped faces at BOTH weights, and the ink was measured off the PNG. The widest of
21	// the four is what each class is held to:
22	//
23	//                                 Manrope 400   Manrope 700   Fraunces 400   Fraunces 700
24	//     FLASH FLOOD WARNING            326 px        341 px        368 px         385 px
25	//     WARNING                        132           140           150            158
26	//     Move to higher ground now.     376           396           383            409
27	//     nnnnnnnnnn                     177           186           181            195
28	//     WWWWWWWWWW                     280           292           305            323
29	//
30	// The per-class numbers below sit ABOVE every realistic string in that set, so the
31	// estimate errs long and a line wraps early rather than running out of its box.
32	// `tests/type_fit.mjs` holds those measurements as fixtures and fails if a change
33	// makes the estimate optimistic about any of them.
34	//
35	// THEY WERE RE-MEASURED WHEN THE FACES CHANGED, and they had to be. The first set was
36	// taken from DejaVu Serif, which is what a Linux box substitutes for the Georgia this
37	// engine used to ask for and never shipped. Manrope's lowercase is wider: a run of
38	// n's measures 0.62 em against DejaVu's 0.497, so the old `lower: 0.52` was under the
39	// truth the moment the typeface changed. **A width table belongs to a face**, and
40	// changing the face without re-measuring would have put the estimate below reality
41	// while every gate still reported green.
42	//
43	// WHAT THIS CANNOT DO, said plainly. It is an estimate of a proportional face, so a
44	// string of nothing but capital Ms or Ws is under-counted, by up to 1.3x for a run of
45	// Ws in Fraunces. Those two runs are in the fixtures as a record of the limit rather
46	// than as a bound the estimate has to clear. Wrapping is what makes it survivable: a
47	// wrong width estimate moves a line break, where a hand-tuned font size moved text
48	// off the edge.
49	// =============================================================================
50	
51	/**
52	 * THE THREE STACKS, WRITTEN DOWN ONCE.
53	 *
54	 * `Georgia, serif` was written out at 61 sites, `ui-monospace, monospace` at 8 and
55	 * `'JetBrains Mono', monospace` at 5, and none of those faces was shipped. A stack
56	 * restated in seventy places is a stack that will be wrong in one of them, and here
57	 * every one of them was wrong at once.
58	 *
59	 * `display` is the film's voice and the sheets' headings. `body` is everything a
60	 * reader reads at length, and everything drawn INSIDE the world as user interface,
61	 * because a phone does not set its alerts in a display serif. `mono` is data.
62	 *
63	 * The fallbacks after each family are what a machine without the shipped face would
64	 * use. They are there so a missing file degrades instead of disappearing, not because
65	 * anything is expected to reach them: `font_check.py` refuses a family this repo does
66	 * not ship.
67	 */
68	export const FONT = {
69	  display: '"Fraunces", Georgia, serif',
70	  body: '"Manrope", system-ui, sans-serif',
71	  mono: '"JetBrains Mono", ui-monospace, monospace',
72	} as const;
73	
74	/** Advance width in ems, per character class, ABOVE the measured worst realistic case. */
75	const EM = {
76	  upper: 0.74,   // real headlines run 0.572 to 0.752 across the four faces
77	  lower: 0.62,   // sentences run 0.482 to 0.558, a run of n's reaches 0.620
78	  digit: 0.65,
79	  space: 0.30,
80	  punct: 0.40,
81	} as const;
82	
83	/** Bold against regular, measured across both faces at about 1.05x. */
84	const BOLD = 1.08;
85	
86	const classOf = (ch: string): keyof typeof EM => {
87	  if (ch === ' ') return 'space';
88	  if (ch >= '0' && ch <= '9') return 'digit';
89	  if (ch >= 'A' && ch <= 'Z') return 'upper';
90	  if (ch >= 'a' && ch <= 'z') return 'lower';
91	  return 'punct';
92	};
93	
94	/**
95	 * How wide `s` is, in ems, erring long.
96	 *
97	 * Multiply by the font size to get draw units in the frame the text is drawn in.
98	 */
99	export function widthEm(s: string, bold = false): number {
100	  let w = 0;
101	  for (const ch of s) w += EM[classOf(ch)];
102	  return bold ? w * BOLD : w;
103	}
104	
105	/** Draw units, which is what a caller with a box actually wants to compare against. */
106	export const widthOf = (s: string, fontSize: number, bold = false) =>
107	  widthEm(s, bold) * fontSize;
108	
109	/**
110	 * Break `s` into lines that each fit `maxUnits` at `fontSize`.
111	 *
112	 * A word longer than the whole line is NOT broken mid-word and NOT dropped: it goes
113	 * on a line of its own and overflows, because a silently truncated warning is worse
114	 * than an ugly one and a caller needs to be able to see what they did. `overflows`
115	 * reports it so a gate can refuse it.
116	 */
117	export function wrapToWidth(
118	  s: string, maxUnits: number, fontSize: number, bold = false,
119	): string[] {
120	  const lines: string[] = [];
121	  let line = '';
122	  for (const word of s.split(/\s+/).filter(Boolean)) {
123	    const candidate = line ? `${line} ${word}` : word;
124	    if (line && widthOf(candidate, fontSize, bold) > maxUnits) {
125	      lines.push(line);
126	      line = word;
127	    } else {
128	      line = candidate;
129	    }
130	  }
131	  if (line) lines.push(line);
132	  return lines.length ? lines : [''];
133	}
134	
135	/**
136	 * Break text to a measured width, including an otherwise unbreakable token.
137	 *
138	 * This is for display-only provenance such as a commit-pinned URL.  Every character is kept,
139	 * and an overlong token is continued on the next visual line without adding a hyphen or other
140	 * character that is not part of the source.  Ordinary editorial copy should keep using
141	 * `wrapToWidth`, whose refusal to disguise an overlong word is the safer default.
142	 */
143	export function wrapBreakableToWidth(
144	  s: string, maxUnits: number, fontSize: number, bold = false,
145	): string[] {
146	  const lines: string[] = [];
147	  let line = '';
148	  const flush = () => {
149	    if (line) lines.push(line);
150	    line = '';
151	  };
152	
153	  for (const word of s.split(/\s+/).filter(Boolean)) {
154	    const pieces: string[] = [];
155	    let piece = '';
156	    for (const ch of word) {
157	      if (piece && widthOf(piece + ch, fontSize, bold) > maxUnits) {
158	        pieces.push(piece);
159	        piece = ch;
160	      } else {
161	        piece += ch;
162	      }
163	    }
164	    if (piece) pieces.push(piece);
165	
166	    for (let i = 0; i < pieces.length; i++) {
167	      const candidate = line ? `${line}${i === 0 ? ' ' : ''}${pieces[i]}` : pieces[i];
168	      if (line && widthOf(candidate, fontSize, bold) > maxUnits) {
169	        flush();
170	        line = pieces[i];
171	      } else {
172	        line = candidate;
173	      }
174	      // A continuation of one unbroken token must start on the next visual line.
175	      if (i < pieces.length - 1) flush();
176	    }
177	  }
178	  flush();
179	  return lines.length ? lines : [''];
180	}
181	
182	/** The lines of `s` that still do not fit, which is only ever an unbreakable word. */
183	export const overflows = (
184	  s: string, maxUnits: number, fontSize: number, bold = false,
185	): string[] =>
186	  wrapToWidth(s, maxUnits, fontSize, bold)
187	    .filter((l) => widthOf(l, fontSize, bold) > maxUnits);
