26	const ArtContext = createContext<ArtDirection | undefined>(undefined);
27	const CameraContext = createContext<ShotPose | undefined>(undefined);
28	export const useArtDirection = () => useContext(ArtContext);
29	export const useDirectedCamera = () => useContext(CameraContext);
30	export const ArtDirectionProvider: React.FC<{profile?: ArtDirection; scenes?:DirectedScene[]; children: React.ReactNode}> =
31	  ({profile, scenes=[], children}) => {
32	    // Read the film clock above Sequences and the Three.js portal. Child-local
33	    // clocks must never restart an authored camera event.
34	    const time=useCurrentFrame()/useVideoConfig().fps;
35	    const windows=useMemo(()=>profile?actionWindows(scenes):{},[profile,scenes]);
36	    if (profile && (profile.version !== 'directed-world-v1' || !profile.palette || !profile.lighting)) {
37	      throw new Error('Invalid art direction profile; validate the board before rendering');
38	    }
39	    const camera=artShotAt(profile,scenes,windows,time);
40	    return <ArtContext.Provider value={profile}><CameraContext.Provider value={camera}>{children}</CameraContext.Provider></ArtContext.Provider>;
41	  };
42	
43	export function artShotAt(profile:ArtDirection|undefined,scenes:DirectedScene[],windows:Record<string,ActionWindow>,time:number):ShotPose|undefined{
44	  const scene=scenes.find(s=>time>=s.start_s&&time<s.start_s+s.duration_s);
45	  return scene?directedShot(profile,scene.id,windows,time):undefined;
46	}
47	
48	/** Follow an authored event; a held shot has no synthetic camera movement. */
49	export function directedShot(profile: ArtDirection | undefined, sceneId: string,
50	  windows: Record<string, ActionWindow>, time: number): ShotPose | undefined {
51	  const shot = profile?.shots[sceneId];
52	  if (!shot) return undefined;
53	  if (!shot.event_id || !shot.to) return shot;
54	  const p = actionProgress(requireAction(windows, shot.event_id), time);
55	  const lerp = (a: number, b: number) => a + (b - a) * p;
56	  return {position: shot.position.map((v,i)=>lerp(v,shot.to!.position[i])) as V3,
57	    target: shot.target.map((v,i)=>lerp(v,shot.to!.target[i])) as V3,
58	    fov: lerp(shot.fov,shot.to.fov)};
59	}
