1	import {SAFE_BOTTOM, SAFE_RIGHT} from './safearea';
2	import {widthOf, wrapBreakableToWidth, wrapToWidth} from './type';
3	
4	export const CAPTION_BAND = {left: 36, padding: 12, right: SAFE_RIGHT, bottom: SAFE_BOTTOM};
5	export const CAPTION_TEXT_WIDTH = CAPTION_BAND.right - CAPTION_BAND.left - 2 * CAPTION_BAND.padding;
6	export const CAPTION_ENTRANCE_PX = 6;
7	
8	/** The lowest two-line size a cue that declares max_lines 3 keeps before it may take a third line. */
9	export const CAPTION_THIRD_LINE_BELOW = 34;
10	/** The sizes a declared three-line cue may use. Below these it keeps its two-line layout. */
11	const THIRD_LINE_SIZES = [44, 42, 40];
12	
13	/** The caption band's height for a layout, in the same arithmetic the band is drawn with. */
14	export const captionBandHeight = (fit: {lines: string[]; size: number}): number =>
15	  fit.lines.length * (fit.size * 1.23) + 20;
16	
17	/** Balanced lines of complete phrases at one size, or null when `count` lines can't hold them. */
18	function balanced(words: string[], text: string, width: number, size: number, maxLines: number): string[] | null {
19	  const greedy = wrapToWidth(text, width, size, true);
20	  if (greedy.length > maxLines || greedy.some((line) => widthOf(line, size, true) > width)) return null;
21	  const count = greedy.length;
22	  const target = widthOf(words.join(' '), size, true) / count;
23	  // Minimise raggedness across the lines,
24	  // so a lone trailing word doesn't hang below a nearly full paragraph.
25	  const solve = (start: number, remaining: number): {lines: string[]; cost: number} | null => {
26	    if (!remaining) return start === words.length ? {lines: [], cost: 0} : null;
27	    let best: {lines: string[]; cost: number} | null = null;
28	    for (let end = start + 1; end <= words.length - remaining + 1; end++) {
29	      const line = words.slice(start, end).join(' ');
30	      const measured = widthOf(line, size, true);
31	      if (measured > width) break;
32	      const tail = solve(end, remaining - 1);
33	      if (!tail) continue;
34	      const cost = (measured - target) ** 2 + tail.cost;
35	      if (!best || cost < best.cost) best = {lines: [line, ...tail.lines], cost};
36	    }
37	    return best;
38	  };
39	  return solve(0, count)?.lines ?? greedy;
40	}
41	
42	/** Balance complete phrases without inventing word timings or dropping a word.
43	 *
44	 * At most two lines. A measured cue that has no measured silence to split at and declares
45	 * `max_lines: 3` in captions.json may take a third line, only when two lines would fall
46	 * below CAPTION_THIRD_LINE_BELOW and three lines hold it at 40 or more. A cue without the
47	 * declaration lays out exactly as before. */
48	export function captionLayout(text: string, width: number, maxLines = 2): {lines: string[]; size: number} {
49	  const words = text.trim().split(/\s+/).filter(Boolean);
50	  if (!words.length) return {lines: [], size: 48};
51	  let two: {lines: string[]; size: number} | null = null;
52	  for (const size of [44, 42, 40, 38, 36, 34, 32, 30, 29]) {
53	    const lines = balanced(words, text, width, size, 2);
54	    if (lines) { two = {lines, size}; break; }
55	  }
56	  if (maxLines >= 3 && (!two || two.size < CAPTION_THIRD_LINE_BELOW)) {
57	    for (const size of THIRD_LINE_SIZES) {
58	      const lines = balanced(words, text, width, size, 3);
59	      if (lines) return {lines, size};
60	    }
61	  }
62	  if (two) return two;
63	  throw new Error('Caption is too dense for two readable lines. Rebuild shorter cues from measured speech boundaries.');
64	}
