66	export type CreditRow = {text: string; heading: boolean; y: number; size: number};
67	
68	/** Keep the supplied source/music text intact; the masthead supplies the brand separately. */
69	export function creditLayout(text: string, width: number, top: number, bottom: number): CreditRow[] {
70	  const raw = text.split('\n').map((line) => line.trim()).filter(Boolean)
71	    .filter((line) => line.toUpperCase() !== 'TEXAS AI DOCKET');
72	  for (const size of [32, 30, 28, 26]) {
73	    const rows: CreditRow[] = [];
74	    let y = top;
75	    for (const line of raw) {
76	      const heading = line === line.toUpperCase() && line.length < 24;
77	      if (heading && rows.length) y += 22;
78	      // Headers are monospaced with tracking; keep their full advance inside the box.
79	      const rowSize = heading ? 22 : size;
80	      const wrapWidth = heading ? width - line.length * 3 : width;
81	      for (const part of wrapBreakableToWidth(line, wrapWidth, rowSize)) {
82	        y += heading ? 30 : size * 1.32;
83	        rows.push({text: part, heading, y, size: rowSize});
84	      }
85	      if (heading) y += 8;
86	    }
87	    if (y + 10 <= bottom) return rows;
88	  }
89	  throw new Error('Credits exceed the readable end-card area. Use compact source labels and preserve the complete music attribution.');
90	}
